#!/usr/bin/env python3
"""Copyright (c) 2026 NXU Project. All rights reserved.

Rasterize the small SF Pro boot caption before filesystems mount.
"""

from pathlib import Path

from generate_recovery_fonts import emit_bytes, raster_face

ROOT = Path(__file__).resolve().parents[1]
pixels, glyphs, line_height = raster_face(
    ROOT / 'tools/DiskRoot/System/Library/Fonts/SF-Pro-Display-Regular.otf',
    13,
)
header = '''/*
 * Copyright (c) 2026 NXU Project. All rights reserved.
 */
/*
 * File:        kern/boot/status_font.h
 *
 * Small SF Pro boot caption glyphs generated by tools/generate_boot_status_font.py.
 */
#ifndef NXU_BOOT_STATUS_FONT_H
#define NXU_BOOT_STATUS_FONT_H

#include <stdint.h>

typedef struct boot_status_glyph {
	uint32_t offset;
	uint8_t width;
	uint8_t height;
	int8_t x_offset;
	int8_t y_offset;
	uint8_t advance;
} boot_status_glyph_t;

'''
header += f'#define BOOT_STATUS_FONT_HEIGHT {line_height}U\n\n'
header += emit_bytes('g_boot_status_pixels', pixels) + '\n\n'
header += 'static const boot_status_glyph_t g_boot_status_glyphs[95] = {\n'
for offset, width, height, x_offset, y_offset, advance in glyphs:
    header += f'\t{{ {offset}U, {width}U, {height}U, {x_offset}, {y_offset}, {advance}U }},\n'
header += '};\n\n#endif\n'
(ROOT / 'kern/boot/status_font.h').write_text(header)
